-- Management-approved current master costing, 11 October 2026. Original evidence and budgets remain immutable.
CREATE TABLE ubl_cost_revisions (
 configuration_id text NOT NULL REFERENCES ubl_configurations(id), stage text NOT NULL,
 version integer NOT NULL, snapshot jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(configuration_id,stage,version), FOREIGN KEY(configuration_id,stage) REFERENCES ubl_commercial_history(configuration_id,stage)
);
CREATE TRIGGER immutable_ubl_cost_revisions BEFORE UPDATE OR DELETE ON ubl_cost_revisions FOR EACH ROW EXECUTE FUNCTION prevent_master_version_mutation();
INSERT INTO ubl_cost_revisions(configuration_id,stage,version,snapshot)
