CREATE TABLE ubl_site_budget_revisions (
 site_id integer NOT NULL REFERENCES ubl_site_orders(site_id),version integer NOT NULL,
 snapshot jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(site_id,version)
);
CREATE TRIGGER immutable_ubl_site_budget_revisions BEFORE UPDATE OR DELETE ON ubl_site_budget_revisions FOR EACH ROW EXECUTE FUNCTION prevent_master_version_mutation();
INSERT INTO ubl_site_budget_revisions(site_id,version,snapshot)
SELECT o.site_id,1,o.baseline || r.snapshot || jsonb_build_object(
 'markupAmount',((o.baseline->>'sellingExcludingGst')::numeric-(r.snapshot->>'budgetedCost')::numeric)::text,
 'markupPercent',(((o.baseline->>'sellingExcludingGst')::numeric-(r.snapshot->>'budgetedCost')::numeric)/(r.snapshot->>'budgetedCost')::numeric*100)::text)
FROM ubl_site_orders o JOIN ubl_cost_revisions r ON r.configuration_id=o.configuration_id AND r.stage=o.pricing_stage
WHERE o.baseline IS NOT NULL;
CREATE VIEW ubl_effective_site_orders AS
SELECT (jsonb_populate_record(NULL::ubl_site_orders,to_jsonb(o)||jsonb_build_object('baseline',COALESCE(v.snapshot,o.baseline)))).*
FROM ubl_site_orders o LEFT JOIN LATERAL(SELECT snapshot FROM ubl_site_budget_revisions WHERE site_id=o.site_id ORDER BY version DESC LIMIT 1) v ON true;
CREATE VIEW ubl_effective_history_costs AS
SELECT b.configuration_id,b.stage,COALESCE((r.snapshot->>'budgetedCost')::numeric,b.total_cost) AS total_cost,
 COALESCE((r.snapshot->>'panelRate')::numeric,b.panel_rate) AS panel_rate,COALESCE(r.snapshot->>'costBasis',b.basis) AS basis
FROM ubl_history_cost_baselines b LEFT JOIN LATERAL(SELECT snapshot FROM ubl_cost_revisions WHERE configuration_id=b.configuration_id AND stage=b.stage ORDER BY version DESC LIMIT 1) r ON true;
